self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    // add in small batches so one slow file doesn't stall everything
    for (let i = 0; i < ASSETS.length; i += 20) {
      await cache.addAll(ASSETS.slice(i, i + 20).map(u => new Request(u, { cache: 'reload' })));
    }
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter(k => k.startsWith('falepdf-') && k !== CACHE && k !== OCR_CACHE).map(k => caches.delete(k)));
    await self.clients.claim();
  })());
});

// ---- share target inbox (IndexedDB, read by the app on start) ----
function openInbox() {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open('falepdf-inbox', 1);
    req.onupgradeneeded = () => req.result.createObjectStore('inbox', { keyPath: 'id', autoIncrement: true });
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

async function storeShared(files) {
  const db = await openInbox();
  await new Promise((resolve, reject) => {
    const t = db.transaction('inbox', 'readwrite');
    const s = t.objectStore('inbox');
    files.forEach(f => s.add({ file: f, name: f.name, type: f.type, at: Date.now() }));
    t.oncomplete = resolve;
    t.onerror = () => reject(t.error);
  });
  db.close();
}

async function handleShare(request) {
  const scope = self.registration.scope;
  try {
    const form = await request.formData();
    // a share target can also be POSTed by any web page (cross-site form): bounded so it can never fill the device
    let total = 0;
    const files = form.getAll('file').filter(f => f && typeof f === 'object' && f.size > 0).slice(0, 20)
      .filter(f => (total += f.size) <= 200 * 1024 * 1024);
    if (files.length) await storeShared(files);
    return Response.redirect(`${scope}?shared=1#/start`, 303);
  } catch (e) {
    return Response.redirect(`${scope}?share-error=1#/start`, 303);
  }
}

self.addEventListener('fetch', event => {
  const req = event.request;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  // API calls (personal data, quota, tickets) are never answered from or written to a cache
  if (url.pathname.includes('/api/') || url.pathname.includes('/__test/')) return;

  if (req.method === 'POST' && url.pathname.endsWith('/share-target')) {
    event.respondWith(handleShare(req));
    return;
  }
  if (req.method !== 'GET') return;

  // navigations to the app shell: offline-first. Other pages (datenschutz.html, impressum.html, info.html …)
  // go to the network and are never stored as the app shell.
  const scopePath = new URL(self.registration.scope).pathname;
  const isShell = url.pathname === scopePath || url.pathname === scopePath + 'index.html';
  if (req.mode === 'navigate' && !isShell) {
    event.respondWith((async () => {
      try { return await fetch(req); } catch {
        const hit = await (await caches.open(CACHE)).match(req, { ignoreSearch: true });
        return hit || new Response('<h1>Offline</h1>', { headers: { 'Content-Type': 'text/html; charset=utf-8' } });
      }
    })());
    return;
  }
  if (req.mode === 'navigate') {
    event.respondWith((async () => {
      const cache = await caches.open(CACHE);
      const cached = await cache.match('./index.html') || await cache.match('./');
      if (cached) {
        // refresh in the background
        event.waitUntil(fetch(req).then(r => (r.ok ? cache.put('./index.html', r.clone()) : null)).catch(() => {}));
        return cached;
      }
      try { return await fetch(req); } catch { return new Response('<h1>Offline</h1>', { headers: { 'Content-Type': 'text/html; charset=utf-8' } }); }
    })());
    return;
  }

  // OCR engine + language data: cache first (own cache), fetched once on first use
  if (url.pathname.includes('/vendor/tesseract/')) {
    event.respondWith((async () => {
      const cache = await caches.open(OCR_CACHE);
      const hit = await cache.match(req, { ignoreSearch: true });
      if (hit) return hit;
      try {
        const res = await fetch(req);
        if (res.ok && res.type === 'basic' && res.status === 200) cache.put(req, res.clone());
        return res;
      } catch (e) {
        return new Response('', { status: 504, statusText: 'Offline' });
      }
    })());
    return;
  }

  // static assets: cache first, then network (and store)
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const hit = await cache.match(req, { ignoreSearch: true });
    if (hit) return hit;
    try {
      const res = await fetch(req);
      if (res.ok && res.type === 'basic') cache.put(req, res.clone());
      return res;
    } catch (e) {
      return new Response('', { status: 504, statusText: 'Offline' });
    }
  })());
});
